<script>export let data;export let form;</script>
<div class="page-intro"><div><a href="/dashboard">← Back to dashboard</a><p class="eyebrow">Find your people</p><h1>Join a group</h1><p class="muted">Request to join an existing group. The group creator will approve your request before you can see its expenses.</p></div></div>
{#if form?.error}<p class="error" role="alert">{form.error}</p>{/if}{#if form?.success}<p class="success" role="status">{form.success}</p>{/if}
<form class="search" method="GET"><label for="group-search">Search group names</label><div><input id="group-search" name="q" value={data.query} placeholder="e.g. Apartment 4B" /><button class="button secondary">Search</button></div></form>
<section class="group-grid">{#if data.groups.length}{#each data.groups as group}<article class="card group-card"><div class="group-heading"><span class="avatar">{group.name[0].toUpperCase()}</span><div><h2>{group.name}</h2><p class="muted">Created by {group.creatorName}</p></div></div><p class="member-count">{group.memberCount} member{group.memberCount===1?'':'s'}</p>{#if group.isMember}<span class="status">You are already a member</span>{:else if group.requestStatus==='pending'}<span class="status">Request pending</span>{:else}<form method="POST" action="?/request"><input type="hidden" name="groupId" value={group.id} /><button class="button">Request to join</button></form>{/if}</article>{/each}{:else}<div class="card empty"><p>No groups matched your search.</p><a href="/groups/join" class="button secondary">Show all groups</a></div>{/if}</section>
<style>.page-intro{margin:2rem 0 1.5rem}.eyebrow{color:#d26d35;font-size:.8rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;margin:1.5rem 0 .4rem}.page-intro h1{font-size:clamp(2rem,5vw,3.2rem);margin:.3rem 0}.muted{color:#58746b}.search{margin:1.5rem 0}.search label{display:block;margin-bottom:.4rem}.search>div{display:flex;gap:.6rem}.search input{flex:1}.group-grid{display:grid;gap:1rem;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}.group-card{display:flex;flex-direction:column;gap:.8rem}.group-heading{align-items:center;display:flex;gap:.75rem}.group-heading h2{font-size:1.15rem;margin:0}.group-heading p{margin:.2rem 0 0}.avatar{align-items:center;background:#d6f2e4;border-radius:10px;color:#146c52;display:flex;font-weight:800;height:2.5rem;justify-content:center;width:2.5rem}.member-count{margin:0}.status{background:#e6f2ed;border-radius:7px;color:#146c52;font-size:.9rem;padding:.6rem .7rem}.success{background:#e6f2ed;border:1px solid #b8deca;border-radius:8px;color:#146c52;padding:.75rem}.empty{color:#58746b;text-align:center}@media(max-width:600px){.search>div{align-items:stretch;flex-direction:column}}</style>
